      <EmployeeList
        employees={employees}
        deleteEmployee={deleteEmployee}
      />

      <EmployeeProfileUpdate
        employees={employees}
        updateEmployee={updateEmployee}
      />

      <EmployeeSearch employees={employees} />
    </div>
  );
}

export default App;
